### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
const ll NEG_INF = -0x3f3f3f3f3f3f3f3fLL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, K;
        cin >> N >> K;
        vector<ll> a(N + 1), prefix(N + 1, 0);
        for (int i = 1; i <= N; i++) {
            cin >> a[i];
            prefix[i] = prefix[i - 1] + a[i];
        }

        // dp[i][j] 表示前 i 个关卡划分为 j 个阶段的最大总得分
        vector<vector<ll>> dp(N + 1, vector<ll>(K + 1, NEG_INF));
        dp[0][0] = 0;

        // 枚举阶段编号 j
        for (int j = 1; j <= K; j++) {
            // 奇数阶段权值为 1，偶数阶段为 2
            ll w = (j % 2 == 1) ? 1 : 2;
            ll max_val = NEG_INF;
            // i 至少为 j
            for (int i = j; i <= N; i++) {
                // 候选分界点 l = i - 1
                if (i - 1 >= j - 1) {
                    max_val = max(max_val, dp[i - 1][j - 1] - w * prefix[i - 1]);
                }
                dp[i][j] = w * prefix[i] + max_val;
            }
        }

        cout << dp[N][K] << "\n";
    }
    return 0;
}
